import{bV as t,aL as e,u as l,G as i}from"./chunks/framework.BfzMay2U.js";const p=JSON.parse('{"title":"PHP/Laravel 开发面试指南","description":"","frontmatter":{"title":"PHP/Laravel 开发面试指南","date":"2026-09-29T10:00:00.000Z","categories":["面试，PHP"],"tags":["Laravel","MySQL","UniApp","MES","ERP","OA"],"sidebar":"auto"},"headers":[],"relativePath":"php/index.md","filePath":"php/index.md"}'),r={name:"php/index.md"};function o(d,a,n,h,s,c){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="php-laravel-全栈开发面试指南" tabindex="-1">PHP/Laravel 全栈开发面试指南 <a class="header-anchor" href="#php-laravel-全栈开发面试指南" aria-label="Permalink to &quot;PHP/Laravel 全栈开发面试指南&quot;">​</a></h1><p>本文档针对<strong>MES、E-DHR、ERP、OA 系统集成</strong>方向的 PHP 开发岗位，整理相关面试知识点和实战题目。</p><h2 id="核心技能要求" tabindex="-1">核心技能要求 <a class="header-anchor" href="#核心技能要求" aria-label="Permalink to &quot;核心技能要求&quot;">​</a></h2><h3 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h3><ul><li><strong>后端</strong>: PHP 7.4+ / 8.x + Laravel框架</li><li><strong>数据库</strong>: MySQL 5.7+ / 8.x (优化、事务、锁机制)</li><li><strong>前端/移动端</strong>: UniApp（微信小程序、APP开发）</li><li><strong>系统集成</strong>: RESTful API、第三方系统对接</li><li><strong>运维</strong>: Linux、Docker、Nginx</li></ul><h3 id="业务领域" tabindex="-1">业务领域 <a class="header-anchor" href="#业务领域" aria-label="Permalink to &quot;业务领域&quot;">​</a></h3><ul><li>MES（制造执行系统）</li><li>ERP（企业资源计划）</li><li>E-DHR（电子批记录）</li><li>OA（办公自动化）</li><li>设备联网与数据采集</li></ul><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><h3 id="本次-jd-专项-150-道面试题与参考回答" tabindex="-1">本次 JD 专项：150 道面试题与参考回答 <a class="header-anchor" href="#本次-jd-专项-150-道面试题与参考回答" aria-label="Permalink to &quot;本次 JD 专项：150 道面试题与参考回答&quot;">​</a></h3><p>围绕 Laravel + MySQL + UniApp，以及 MES、E-DHR、ERP 对接、OA 流程、设备联网、测试上线和技术文档整理。每题包含参考回答与追问要点，适合先自答再核对；场景案例不代表已经交付的个人经历。</p><table tabindex="0"><thead><tr><th>篇目</th><th>题号</th><th>重点</th></tr></thead><tbody><tr><td><a href="./jd/laravel-php-interview.html">Laravel 与后端开发</a></td><td>01—25</td><td>PHP 基础、请求链路、权限、队列、事务、安全</td></tr><tr><td><a href="./jd/mysql-concurrency-interview.html">MySQL、并发与报表</a></td><td>26—50</td><td>数据建模、索引、锁、扣料防重、统计口径、恢复</td></tr><tr><td><a href="./jd/integration-device-interview.html">系统集成与设备联网</a></td><td>51—75</td><td>ERP/OA/MES 对接、幂等、重试、对账、工业协议</td></tr><tr><td><a href="./jd/mes-edhr-oa-interview.html">MES、E-DHR 与 OA</a></td><td>76—100</td><td>工单、批次、质量、电子记录、签名、审批流程</td></tr><tr><td><a href="./jd/uniapp-mobile-interview.html">UniApp、小程序与 APP</a></td><td>101—125</td><td>登录、扫码、离线队列、冲突恢复、真机与发布</td></tr><tr><td><a href="./jd/delivery-troubleshooting-interview.html">测试、上线与需求协作</a></td><td>126—150</td><td>并发测试、软件验证、故障排查、受控发布、项目表达</td></tr></tbody></table><p>建议按题号顺序阅读。时间有限时，可先查看<a href="./jd/delivery-troubleshooting-interview.html#自测与复习安排">自测与复习安排</a>，再针对薄弱部分补习下方原有专题。</p><h3 id="基础篇" tabindex="-1">基础篇 <a class="header-anchor" href="#基础篇" aria-label="Permalink to &quot;基础篇&quot;">​</a></h3><ul><li><a href="./basic/php-core-questions.html">PHP 核心面试题</a> - PHP 语言特性、面向对象、内存管理</li><li><a href="./basic/mysql-fundamentals.html">MySQL 必考题</a> - 索引优化、事务隔离、锁机制</li><li><a href="./basic/laravel-framework-deep-dive.html">Laravel 框架深入</a> - 服务容器、中间件、事件机制</li></ul><h3 id="进阶篇" tabindex="-1">进阶篇 <a class="header-anchor" href="#进阶篇" aria-label="Permalink to &quot;进阶篇&quot;">​</a></h3><ul><li><a href="./advanced/system-integration-api.html">系统接口设计与集成</a> - ERP/OA/MES系统对接实践</li><li><a href="./advanced/unibapp-mini-program-app.html">UniApp 跨平台开发</a> - 小程序与 APP开发最佳实践</li><li><a href="./advanced/data-consistency-traceability.html">生产数据一致性与追溯</a> - MES系统数据完整性设计</li></ul><h3 id="实战篇" tabindex="-1">实战篇 <a class="header-anchor" href="#实战篇" aria-label="Permalink to &quot;实战篇&quot;">​</a></h3><ul><li><a href="./projects/factory-digitalization-case-study.html">工厂数字化项目实战</a> - MES系统从需求到上线全流程</li><li><a href="./projects/medical-compliance-system.html">医疗器械合规系统设计</a> - E-DHR 系统审计追踪实现</li><li><a href="./projects/device-connectivity-data-collection.html">设备联网与数据采集</a> - PLC/SCADA 设备对接方案</li></ul><h3 id="软技能篇" tabindex="-1">软技能篇 <a class="header-anchor" href="#软技能篇" aria-label="Permalink to &quot;软技能篇&quot;">​</a></h3><ul><li><a href="./soft/self-introduction-templates.html">自我介绍模板</a> - 针对不同阶段的表达策略</li><li><a href="./soft/resume-key-points.html">简历突出要点</a> - PHP 开发简历优化指南</li><li><a href="./soft/requirement-translation.html">技术沟通与需求转化</a> - 业务需求转技术方案技巧</li><li><a href="./soft/medical-manufacturing-interview-guide.html">医疗制造业岗位定向准备</a> - 基于个人简历和岗位职责的面试回答与补强清单</li></ul><h2 id="面试流程建议" tabindex="-1">面试流程建议 <a class="header-anchor" href="#面试流程建议" aria-label="Permalink to &quot;面试流程建议&quot;">​</a></h2><ol><li><strong>技术笔试</strong>：PHP 语法、SQL 优化、Laravel 使用</li><li><strong>专业面试</strong>：系统设计、问题排查、性能优化</li><li><strong>业务理解</strong>：MES/ERP/OA业务流程、设备对接场景</li><li><strong>综合素质</strong>：沟通能力、项目管理、文档编写</li></ol><div class="info custom-block"><p class="custom-block-title">提示</p><p>建议按照 &quot;基础 → 进阶 → 实战&quot; 的顺序逐步学习，每个模块都包含理论知识点和实战案例。</p></div>',23)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
